const isWebhook = $json.body !== undefined;
const input = isWebhook ? $json.body : $json;

return [{
  json: {
    orderNumber: String(input.orderNumber || '').trim(),
    email: String(input.email || '').trim().toLowerCase(),
    viaWebhook: isWebhook,
  },
}];

const input = $('Normalize Input').first().json;
const orderResult = $json;

const GENERIC_FAIL = "We couldn't verify an order with that order number and email combination. Please double-check both and try again, or contact us at dennisphx18@gmail.com if you need help.";

if (!input.orderNumber || !input.email || orderResult.error || !orderResult.id) {
  return [{ json: { success: false, message: GENERIC_FAIL, viaWebhook: input.viaWebhook } }];
}

const billingEmail = (orderResult.billing?.email || '').trim().toLowerCase();
if (billingEmail !== input.email) {
  return [{ json: { success: false, message: GENERIC_FAIL, viaWebhook: input.viaWebhook } }];
}

const items = (orderResult.line_items || []).map((li) => `${li.quantity}x ${li.name}`).join(', ') || 'none listed';
const shipping = orderResult.shipping?.address_1 ? orderResult.shipping : orderResult.billing;
const address = [shipping?.address_1, shipping?.address_2, shipping?.city, shipping?.state, shipping?.postcode]
  .filter(Boolean)
  .join(', ');

const message = `Order #${orderResult.number} status: ${orderResult.status}. Items: ${items}. Total: ${orderResult.currency} ${orderResult.total}.` +
  (address ? ` Delivery address: ${address}.` : '');

return [{
  json: {
    success: true,
    message,
    order: {
      number: orderResult.number,
      status: orderResult.status,
      total: orderResult.total,
      currency: orderResult.currency,
      items,
      address,
    },
    viaWebhook: input.viaWebhook,
  },
}];
